pm.test("A API devolve HTTP 404", function () {
    pm.response.to.have.status(404);
});

pm.test("A mensagem indica pedido inexistente", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.detail).to.eql(
        "Pedido não encontrado"
    );
});

pm.test("A resposta é um objeto JSON", function () {
    const resposta = pm.response.json();

    pm.expect(resposta).to.be.an("object");
});

pm.test("A API devolve HTTP 201", function () {
    pm.response.to.have.status(201);
});

pm.test("O pedido recebe um ID válido", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.id).to.be.a("number");
    pm.expect(resposta.id).to.be.above(0);
});

pm.test("A resposta confirma a criação do pedido", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.message).to.eql(
        "Pedido criado com sucesso"
    );
});

pm.test("Os dados devolvidos correspondem aos enviados", function () {
    const resposta = pm.response.json();
    const enviado = JSON.parse(pm.request.body.raw);

    pm.expect(resposta.cliente).to.eql(enviado.cliente);
    pm.expect(resposta.produto).to.eql(enviado.produto);
    pm.expect(resposta.quantidade).to.eql(enviado.quantidade);
    pm.expect(resposta.estado).to.eql(enviado.estado);
});

pm.test("A API devolve HTTP 422", function () {
    pm.response.to.have.status(422);
});

pm.test("O erro está relacionado com a quantidade", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.detail).to.be.an("array");

    const erroQuantidade = resposta.detail.find(
        erro => erro.loc.includes("quantidade")
    );

    pm.expect(erroQuantidade).to.exist;
    pm.expect(erroQuantidade.type).to.eql("greater_than");
});

pm.test("O valor inválido é -2", function () {
    const resposta = pm.response.json();

    const erroQuantidade = resposta.detail.find(
        erro => erro.loc.includes("quantidade")
    );

    pm.expect(erroQuantidade.input).to.eql(-2);
});
